function SettingsPageNew({ theme, chooseTheme, handleLogo, logo }: { theme: ThemeName, chooseTheme: (t: ThemeName) => void, handleLogo: (e: React.ChangeEvent<HTMLInputElement>) => void, logo: string | null }) { const [tab, setTab] = useState('Apparence'); const [saved, setSaved] = useState(false); const [company, setCompany] = useState({ name: 'CCAI-CI SARL', rccm: 'CI-ABJ-2024-B-18342', phone: '+225 27 22 45 18 90', email: 'contact@ccai-ci.ci', address: 'Cocody Riviera 3, Abidjan' }); const [thresholds, setThresholds] = useState([['Dépense','0','5 000 000','Responsable chantier'],['Dépense','5 000 001','25 000 000','RH'],['Facture','0','10 000 000','Admin']]); const save = () => { localStorage.setItem('ccai-company', JSON.stringify(company)); localStorage.setItem('ccai-thresholds', JSON.stringify(thresholds)); setSaved(true); window.setTimeout(() => setSaved(false), 1800) }; return <div><div className="mb-6"><p className="mb-2 text-sm font-medium text-slate-400">Configuration</p><h1 className="text-3xl font-bold tracking-tight">Paramètres</h1><p className="mt-2 text-sm text-muted-foreground">Personnalisez l&apos;expérience de CCAI-CI SARL.</p></div><div className="mb-6 flex gap-1 overflow-x-auto border-b border-border">{['Apparence','Entreprise','Seuils de validation'].map(item => <button key={item} onClick={() => setTab(item)} className={`whitespace-nowrap border-b-2 px-4 py-3 text-sm font-bold ${tab === item ? 'border-[var(--nav-underline)] text-foreground' : 'border-transparent text-muted-foreground'}`}>{item}</button>)}</div>{tab === 'Apparence' && <Card><div className="flex flex-col gap-6 md:flex-row md:items-center md:justify-between"><div><h2 className="font-bold">Identité visuelle</h2><p className="mt-1 text-sm text-muted-foreground">Choisissez une palette et gérez le logo affiché dans le menu.</p></div>{logo ? <div className="flex items-center gap-3"><img src={logo} alt="Logo entreprise" className="size-14 rounded-xl border border-border object-contain" /><button onClick={() => { localStorage.removeItem('ccai-logo'); location.reload() }} className="rounded-lg border border-border px-3 py-2 text-xs font-bold">Supprimer le logo</button></div> : <label className="cursor-pointer rounded-lg border border-dashed border-border px-4 py-3 text-xs font-bold"><Upload className="mr-2 inline size-4" />Importer un logo<input type="file" accept="image/*" onChange={handleLogo} className="hidden" /></label>}</div><div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{(Object.entries(themes) as [ThemeName, typeof themes[ThemeName]][]).map(([key, item]) => <button key={key} onClick={() => chooseTheme(key)} className={`overflow-hidden rounded-xl border-2 text-left transition ${theme === key ? 'border-[var(--nav-underline)] shadow-lg' : 'border-border hover:border-muted-foreground'}`}><div className="h-20" className={`h-20 theme-preview-${key}`} /><div className="flex items-center justify-between bg-card p-4"><span className="text-sm font-bold">{item.label}</span>{theme === key && <Check className="size-4 text-[var(--accent)]" />}</div></button>)}</div></Card>}{tab === 'Entreprise' && <Card><h2 className="font-bold">Informations de l&apos;entreprise</h2><div className="mt-6 grid gap-4 md:grid-cols-2">{Object.entries(company).map(([key, value]) => <label key={key} className="text-xs font-bold capitalize text-muted-foreground">{key === 'rccm' ? 'RCCM' : key}<input value={value} onChange={e => setCompany({ ...company, [key]: e.target.value })} className="mt-2 w-full rounded-lg border border-border bg-background px-3 py-3 text-sm font-normal text-foreground outline-none focus:border-[var(--accent)]" /></label>)}</div></Card>}{tab === 'Seuils de validation' && <Card><h2 className="font-bold">Seuils de validation</h2><p className="mt-1 text-sm text-muted-foreground">Réservé aux administrateurs.</p><div className="mt-6 overflow-x-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="bg-muted text-muted-foreground"><tr><th className="p-3">Opération</th><th className="p-3">Minimum</th><th className="p-3">Maximum</th><th className="p-3">Validateur</th></tr></thead><tbody>{thresholds.map((row, i) => <tr key={i} className="border-b border-border">{row.map((cell, j) => <td key={j} className="p-3"><input value={cell} onChange={e => setThresholds(thresholds.map((r, ri) => ri === i ? r.map((c, ci) => ci === j ? e.target.value : c) : r))} className="w-full rounded border border-border bg-background px-2 py-2 text-xs" /></td>)}</tr>)}</tbody></table></div></Card>}<div className="mt-6 flex justify-end"><button onClick={save} className="rounded-lg bg-[var(--primary)] px-5 py-3 text-sm font-bold text-[var(--primary-fg)]">{saved ? 'Enregistré' : 'Enregistrer les modifications'}</button></div></div> }

function LegacySettingsPage({ theme, chooseTheme, handleLogo, logo }: { theme: ThemeName, chooseTheme: (t: ThemeName) => void, handleLogo: (e: React.ChangeEvent<HTMLInputElement>) => void, logo: string | null }) { const [userDrawer, setUserDrawer] = useState(false); const [userTab, setUserTab] = useState('Tous'); const [users, setUsers] = useState([['Aminata Diarra','aminata@ccai-ci.ci','Admin','Actif','12 oct. 2026'],['Kouadio N’Guessan','kouadio@ccai-ci.ci','Responsable chantier','Actif','11 oct. 2026'],['Awa Bamba','awa.bamba@ccai-ci.ci','RH','Actif','10 oct. 2026'],['Moussa Traoré','moussa.traore@ccai-ci.ci','Employé','Inactif','28 sept. 2026'],['Saliha Koné','saliha.kone@ccai-ci.ci','Employé','Actif','08 oct. 2026']]); const filteredUsers = users.filter(u => userTab === 'Tous' || u[3] === userTab); const [thresholds, setThresholds] = useState([['Dépense','0','5 000 000','Responsable chantier'],['Dépense','5 000 001','25 000 000','RH'],['Facture','0','10 000 000','Admin'],['Démarrage de chantier','0','100 000 000','Admin']]); const [thresholdSaved, setThresholdSaved] = useState(false); const addThreshold = () => setThresholds([...thresholds, ['Dépense','','','Admin']]); const updateThreshold = (row, col, value) => setThresholds(thresholds.map((item, index) => index === row ? item.map((cell, cellIndex) => cellIndex === col ? value : cell) : item)); return <><Card className="mb-8"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-start"><div><p className="mb-2 text-sm font-medium text-slate-400">Paramètres de contrôle</p><h2 className="text-xl font-bold">Seuils de validation</h2><p className="mt-2 max-w-2xl text-sm text-muted-foreground">Définissez les montants et les rôles requis pour valider chaque opération.</p></div><div className="flex gap-2"><button onClick={addThreshold} className="rounded-lg border border-slate-200 px-4 py-2.5 text-xs font-bold">Ajouter un seuil</button><button onClick={() => { setThresholdSaved(true); setTimeout(() => setThresholdSaved(false), 2200) }} className="rounded-lg bg-[var(--primary)] px-4 py-2.5 text-xs font-bold text-[var(--primary-fg)]">Enregistrer</button></div></div><div className="mt-6 overflow-x-auto"><table className="w-full min-w-[720px] text-left text-xs"><thead className="bg-surface text-muted-foreground"><tr><th className="px-4 py-3 font-semibold">Type d&apos;opération</th><th className="px-4 py-3 font-semibold">Montant minimum (FCFA)</th><th className="px-4 py-3 font-semibold">Montant maximum (FCFA)</th><th className="px-4 py-3 font-semibold">Rôle validateur</th></tr></thead><tbody>{thresholds.map((row, rowIndex) => <tr key={`${row[0]}-${rowIndex}`} className="border-b border-slate-100"><td className="px-4 py-3"><select value={row[0]} onChange={e => updateThreshold(rowIndex, 0, e.target.value)} className="rounded-md border border-slate-200 bg-card px-3 py-2 text-xs font-semibold"><option>Dépense</option><option>Facture</option><option>Démarrage de chantier</option></select></td>{[1,2].map(col => <td key={col} className="px-4 py-3"><input value={row[col]} onChange={e => updateThreshold(rowIndex, col, e.target.value)} className="w-full rounded-md border border-slate-200 px-3 py-2 text-xs outline-none focus:border-[var(--accent)]" placeholder="0" /></td>)}<td className="px-4 py-3"><select value={row[3]} onChange={e => updateThreshold(rowIndex, 3, e.target.value)} className="rounded-md border border-slate-200 bg-card px-3 py-2 text-xs font-semibold"><option>Admin</option><option>RH</option><option>Responsable chantier</option><option>Employé</option></select></td></tr>)}</tbody></table></div><div className="mt-5 flex items-start gap-3 rounded-lg bg-surface p-4 text-xs text-slate-600"><ShieldAlert className="mt-0.5 size-4 shrink-0 text-[var(--accent)]" /><p>Une opération au-dessus du seuil défini nécessite la validation du rôle indiqué avant tout paiement ou démarrage.</p></div>{thresholdSaved && <p className="mt-3 text-xs font-bold text-emerald-600">Seuils enregistrés avec succès.</p>}</Card><Header eyebrow="Administration" title="Utilisateurs" subtitle="Gérez les accès et les équipes de CCAI-CI SARL." action="Inviter un utilisateur" onAction={() => setUserDrawer(true)} /><Card className="mb-8"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-bold">Membres de l’espace</h2><p className="mt-1 text-xs text-slate-400">{users.length} comptes · accès sécurisé par rôle</p></div><div className="flex gap-1 rounded-lg bg-surface p-1">{['Tous','Actif','Inactif'].map(t => <button key={t} onClick={() => setUserTab(t)} className={`rounded-md px-3 py-2 text-xs font-bold ${userTab === t ? 'bg-card text-slate-900 shadow-sm' : 'text-slate-400'}`}>{t}</button>)}</div></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="bg-surface text-muted-foreground"><tr><th className="px-4 py-3 font-semibold">Nom</th><th className="px-4 py-3 font-semibold">Email</th><th className="px-4 py-3 font-semibold">Rôle</th><th className="px-4 py-3 font-semibold">Statut</th><th className="px-4 py-3 font-semibold">Dernière connexion</th><th className="px-4 py-3 font-semibold">Action</th></tr></thead><tbody>{filteredUsers.map((u, i) => <tr key={u[1]} className="border-b border-slate-100"><td className="px-4 py-4"><div className="flex items-center gap-3"><div className="flex size-8 items-center justify-center rounded-full bg-[var(--primary)] text-[10px] font-black text-[var(--primary-fg)]">{u[0].split(' ').map(x => x[0]).join('').slice(0,2)}</div><span className="font-bold">{u[0]}</span></div></td><td className="px-4 py-4 text-muted-foreground">{u[1]}</td><td className="px-4 py-4"><Badge>{u[2]}</Badge></td><td className="px-4 py-4"><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${u[3] === 'Actif' ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-100 text-muted-foreground'}`}>{u[3]}</span></td><td className="px-4 py-4 text-muted-foreground">{u[4]}</td><td className="px-4 py-4">{u[3] === 'Actif' && i > 0 ? <button onClick={() => setUsers(prev => prev.map(x => x[1] === u[1] ? [x[0],x[1],x[2],'Inactif',x[4]] : x))} className="rounded-md border border-orange-200 px-2.5 py-1.5 text-[11px] font-bold text-orange-600 hover:bg-orange-50">Désactiver</button> : <span className="text-slate-300">—</span>}</td></tr>)}</tbody></table></div></Card>{userDrawer && <div className="fixed inset-0 z-50 bg-slate-900/30" onClick={() => setUserDrawer(false)}><aside className="absolute right-0 top-0 h-full w-full max-w-md overflow-y-auto bg-card p-6 shadow-2xl" onClick={e => e.stopPropagation()}><div className="flex items-start justify-between"><div><p className="text-sm font-semibold text-[var(--accent)]">Nouvel accès</p><h2 className="mt-1 text-2xl font-bold">Inviter un utilisateur</h2><p className="mt-2 text-sm text-muted-foreground">Envoyez une invitation avec les droits adaptés.</p></div><button onClick={() => setUserDrawer(false)} className="rounded-md p-2 hover:bg-surface"><X /></button></div><div className="mt-8 flex flex-col gap-4"><label className="text-xs font-bold text-slate-600">Nom complet<input className="mt-2 w-full rounded-lg border border-slate-200 px-3 py-3 text-sm outline-none" placeholder="Ex. Jean Kouassi" /></label><label className="text-xs font-bold text-slate-600">Email professionnel<input type="email" className="mt-2 w-full rounded-lg border border-slate-200 px-3 py-3 text-sm outline-none" placeholder="nom@ccai-ci.ci" /></label><label className="text-xs font-bold text-slate-600">Rôle<select className="mt-2 w-full rounded-lg border border-slate-200 bg-card px-3 py-3 text-sm outline-none"><option>Admin</option><option>RH</option><option>Responsable chantier</option><option>Employé</option></select></label><label className="text-xs font-bold text-slate-600">Chantiers assignés<select multiple className="mt-2 h-28 w-full rounded-lg border border-slate-200 bg-card px-3 py-2 text-sm outline-none">{sites.map(s => <option key={s.name}>{s.name}</option>)}</select><span className="mt-1 block font-normal text-slate-400">Maintenez Ctrl/Cmd pour sélectionner plusieurs chantiers.</span></label><button onClick={() => setUserDrawer(false)} className="mt-3 rounded-lg bg-[var(--primary)] px-4 py-3 text-sm font-bold text-[var(--primary-fg)]">Envoyer l&apos;invitation</button></div></aside></div>}<Header eyebrow="Configuration" title="Paramètres" subtitle="Personnalisez votre espace CCAI-CI." /><Header eyebrow="Configuration" title="Paramètres" subtitle="Personnalisez votre espace CCAI-CI." /><Card className="max-w-5xl"><div className="mb-7 flex items-start gap-3"><div className="flex size-10 items-center justify-center rounded-lg bg-surface text-[var(--accent)]"><Palette className="size-5" /></div><div><h2 className="font-bold">Apparence</h2><p className="mt-1 text-sm text-muted-foreground">Les changements sont appliqués immédiatement.</p></div></div><div className="grid gap-4 md:grid-cols-3">{(Object.keys(themes) as ThemeName[]).map(name => { const item = themes[name]; return <button key={name} onClick={() => chooseTheme(name)} className={`rounded-lg border-2 p-3 text-left ${theme === name ? 'border-[var(--accent)]' : 'border-slate-100'}`}><div className="mb-3 flex h-24 overflow-hidden rounded-md" style={{background:item.sidebar}}><div className="w-1/3 p-2"><div className="mb-2 h-2 w-8 rounded bg-card/30" /><div className="h-1.5 w-10 rounded" style={{background:item.primary}} /></div><div className="flex-1 bg-card p-3"><div className="mb-3 h-2 w-1/2 rounded bg-slate-200" /><div className="grid grid-cols-2 gap-2"><div className="h-9 rounded bg-surface" /><div className="h-9 rounded" style={{background:item.primary}} /></div></div></div><div className="flex items-center justify-between"><span className="text-sm font-bold">{item.label}</span>{theme === name && <span className="rounded-full bg-[var(--primary)] px-2 py-1 text-[10px] font-bold text-[var(--primary-fg)]">Actif</span>}</div></button> })}</div><div className="mt-8 border-t border-slate-100 pt-7"><h2 className="font-bold">Logo de l&apos;entreprise</h2><p className="mt-1 text-sm text-muted-foreground">Ajoutez un logo qui apparaîtra dans le menu latéral.</p><label className="mt-4 flex min-h-28 cursor-pointer items-center justify-center gap-3 rounded-lg border-2 border-dashed border-slate-200 bg-surface p-5 text-sm font-semibold text-muted-foreground"><input type="file" accept="image/*" onChange={handleLogo} className="sr-only" />{logo ? <img src={logo} alt="Aperçu du logo" className="size-16 rounded-lg bg-card object-contain" /> : <><Upload className="size-5" /> Cliquer pour importer un logo</>}</label></div></Card></> }
